func TestRouteCandidateExposesComponentScores(t *testing.T) {
	cand := routing.Candidate{
		Harness:            "fiz",
		Provider:           "local",
		Model:              "model-a",
		Score:              42,
		CostUSDPer1kTokens: 0.012,
